# Create the complete transform function and submit
def transform(grid):
    """
    Transform grid: keep cross of 3s, fill other positions with 4 or 0 based on dr,dc rule
    """
    h_row, v_col = None, None

    # Find horizontal row (all 3s)
    for r in range(len(grid)):
        if all(grid[r][c] == 3 for c in range(len(grid[0]))):
            h_row = r
            break

    # Find vertical column (all 3s)
    for c in range(len(grid[0])):
        if all(grid[r][c] == 3 for r in range(len(grid))):
            v_col = c
            break

    result = []
    for r in range(len(grid)):
        row_out = []
        for c in range(len(grid[0])):
            if r == h_row or c == v_col:
                row_out.append(3)
            else:
                dr = abs(r - h_row)
                dc = abs(c - v_col)

                if dc == 5:
                    row_out.append(0)
                elif dc >= 6:
                    row_out.append(4)
                elif dc == 4:
                    row_out.append(4 if dr < 5 else 0)
                elif dc == 3:
                    row_out.append(4 if dr == 4 else 0)
                elif dc == 1:
                    row_out.append(4 if dr % 2 == 0 else 0)
                elif dc == 2:
                    row_out.append(4 if dr < 3 or dr == 4 else 0)
                else:
                    row_out.append(0)
        result.append(row_out)
    return result

# Test input: 12x12 grid, vert line at col 6, horiz line at row 8
test_input = []
for r in range(12):
    row = [0] * 12
    for c in range(12):
        if r == 8 or c == 6:
            row[c] = 3
    test_input.append(row)

test_output = transform(test_input)

# Verify cross is preserved
assert all(test_output[8][c] == 3 for c in range(12)), "Row 8 should be all 3s"
assert all(test_output[r][6] == 3 for r in range(12)), "Col 6 should be all 3s"

print("Test output:")
for row in test_output:
    print(row)

# Submit
submit_data = {
    "action": "submit",
    "grid": test_output
}

print("\nSubmitting solution...")
print(submit_data)

